mapper.select:
SELECT id, title, theme, logo IS NOT NULL AS has_logo, slide_pagination_position,
       deck_title_position, chapter_title_position, project_logo_position
FROM projects WHERE id = #{projectId}

mapper.update:
UPDATE projects SET slide_pagination_position = #{slidePaginationPosition},
       deck_title_position = #{deckTitlePosition}, chapter_title_position = #{chapterTitlePosition},
       project_logo_position = #{projectLogoPosition}, updated_at = MAX(updated_at + 1, #{updatedAt})
WHERE id = #{id} AND (
    slide_pagination_position IS NOT #{slidePaginationPosition}
    OR deck_title_position IS NOT #{deckTitlePosition}
    OR chapter_title_position IS NOT #{chapterTitlePosition}
    OR project_logo_position IS NOT #{projectLogoPosition}
)
